import json,sys
sys.path.insert(0,'/workspace/submission')
import protocol as P
import fuzz
import random
rnd=random.Random(1)
for trial in range(30):
    ncases=rnd.randint(0,3)
    req={'cases':[fuzz.rand_case(rnd) for _ in range(ncases)]}
    try:
        P.validate(json.loads(json.dumps(req)))
        continue
    except P.InvalidRequest:
        pass
    # bisect per case
    for ci,case in enumerate(req['cases']):
        try:
            P.validate({'cases':[case]})
        except P.InvalidRequest:
            print('case',ci,'illegal')
            print(json.dumps(case)[:1200])
            # find first illegal event
            for n in range(1,len(case['events'])+1):
                c2=json.loads(json.dumps(case)); c2['events']=c2['events'][:n]
                try:
                    P.validate({'cases':[c2]})
                except P.InvalidRequest:
                    print('  fails at event',n-1,json.dumps(case['events'][n-1]))
                    break
            break
    if ci==len(req['cases'])-1: break
PYEOF
